namespace Challenge;public record Cart(decimal Subtotal,bool Vip,string Coupon);public interface IPromotion{decimal Apply(Cart cart,decimal current);}public sealed class PricingEngine(IEnumerable<IPromotion> rules){public int ConfiguredRules=>rules.Count();public decimal Total(Cart cart){var value=cart.Subtotal;if(cart.Vip)value*=.9m;if(cart.Coupon=="SAVE5")value-=5;return value;}}
